def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([-10**4]), fmt([3, 3, 3]), fmt([0, 5]), fmt([1, 9, 2]), fmt([-10**4, 10**4]), fmt([1, 2, 3, 4, 5]), fmt([10, -10, 10, -10])]
    for n in (2, 3, 4, 5, 8, 12, 20, 30):
        for hi in (2, 10):
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    tests.append(fmt([(10**4 if i % 2 == 0 else -10**4) for i in range(100000)]))
    tests.append(fmt([rng.randint(-10**4, 10**4) for _ in range(100000)]))
    tests.append(fmt([rng.randint(-10**4, 10**4) for _ in range(50000)] + [10**4] * 50000))
    tests.append(fmt([-10**4 + (i % 2001) * 10 for i in range(100000)]))
    return tests
